public final class ChickenSell extends JavaPlugin implements Listener{
 private static final int SELL_AREA_END=45,BLOCKS_SLOT=46,MINING_SLOT=47,BOOKS_SLOT=48,SELL_BUTTON_SLOT=49,FARM_SLOT=50,PVP_SLOT=51;
 private static final double[] LEVEL_TARGETS={25000d,150000d,500000d,1000000d,5000000d,25000000d,250000000d,550000000d,850000000d,1000000000d,2000000000d,4000000000d,8000000000d,10000000000d,20000000000d,40000000000d,80000000000d,160000000000d,320000000000d,640000000000d};
 private static final int[] LEVEL_SLOTS={10,19,28,37,38,39,30,21,12,13,14,23,32,41,42,43,34,25,16,7};
 private final Map<Material,Double> prices=new LinkedHashMap<>();private final Map<Material,Category> categories=new HashMap<>();private final List<BookOffer> books=new ArrayList<>();private final Map<UUID,SortMode> sortModes=new HashMap<>();private final Map<UUID,String> searches=new HashMap<>();private final Map<UUID,Category> awaitingSearch=new HashMap<>();private Economy economy;private File dataFile;private YamlConfiguration data;
 @Override public void onEnable(){if(!setupEconomy()){getServer().getPluginManager().disablePlugin(this);return;}loadPrices();loadBooks();loadData();Bukkit.getPluginManager().registerEvents(this,this);getLogger().info("ChickenSell 1.8.1 enabled");}
 private boolean setupEconomy(){RegisteredServiceProvider<Economy> r=getServer().getServicesManager().getRegistration(Economy.class);if(r==null)return false;economy=r.getProvider();return economy!=null;}
 private void add(Material m,double p,Category c){prices.put(m,p);categories.put(m,c);}private void pvp(String name,double p){Material m=Material.matchMaterial(name);if(m!=null)add(m,p,Category.PVP);}private void mining(Material m,double p){add(m,p,Category.MINING);}private void farm(String name,double p){Material m=Material.matchMaterial(name);if(m!=null)add(m,p,Category.FARM_FOOD);}
 private void loadPrices(){for(Material m:Material.values())if(m.isBlock()&&!m.isAir()&&m.isItem())add(m,defaultBlockPrice(m),Category.BLOCKS);Material[] ms={Material.COAL,Material.COAL_ORE,Material.DEEPSLATE_COAL_ORE,Material.COAL_BLOCK,Material.IRON_ORE,Material.DEEPSLATE_IRON_ORE,Material.RAW_IRON,Material.IRON_INGOT,Material.IRON_NUGGET,Material.IRON_BLOCK,Material.COPPER_ORE,Material.DEEPSLATE_COPPER_ORE,Material.RAW_COPPER,Material.COPPER_INGOT,Material.COPPER_BLOCK,Material.GOLD_ORE,Material.DEEPSLATE_GOLD_ORE,Material.NETHER_GOLD_ORE,Material.RAW_GOLD,Material.GOLD_INGOT,Material.GOLD_NUGGET,Material.GOLD_BLOCK,Material.REDSTONE_ORE,Material.DEEPSLATE_REDSTONE_ORE,Material.REDSTONE,Material.REDSTONE_BLOCK,Material.LAPIS_ORE,Material.DEEPSLATE_LAPIS_ORE,Material.LAPIS_LAZULI,Material.LAPIS_BLOCK,Material.DIAMOND_ORE,Material.DEEPSLATE_DIAMOND_ORE,Material.DIAMOND,Material.DIAMOND_BLOCK,Material.EMERALD_ORE,Material.DEEPSLATE_EMERALD_ORE,Material.EMERALD,Material.EMERALD_BLOCK,Material.NETHER_QUARTZ_ORE,Material.QUARTZ,Material.AMETHYST_SHARD,Material.AMETHYST_BLOCK,Material.BUDDING_AMETHYST,Material.SMALL_AMETHYST_BUD,Material.MEDIUM_AMETHYST_BUD,Material.LARGE_AMETHYST_BUD,Material.AMETHYST_CLUSTER,Material.ANCIENT_DEBRIS,Material.NETHERITE_SCRAP,Material.NETHERITE_INGOT,Material.NETHERITE_BLOCK,Material.ECHO_SHARD};for(Material m:ms)mining(m,miningPrice(m));loadFarmFood();loadPvp();}
 private void loadPvp(){String[] names={"WOODEN_SWORD","STONE_SWORD","IRON_SWORD","GOLDEN_SWORD","DIAMOND_SWORD","NETHERITE_SWORD","WOODEN_AXE","STONE_AXE","IRON_AXE","GOLDEN_AXE","DIAMOND_AXE","NETHERITE_AXE","LEATHER_HELMET","LEATHER_CHESTPLATE","LEATHER_LEGGINGS","LEATHER_BOOTS","CHAINMAIL_HELMET","CHAINMAIL_CHESTPLATE","CHAINMAIL_LEGGINGS","CHAINMAIL_BOOTS","IRON_HELMET","IRON_CHESTPLATE","IRON_LEGGINGS","IRON_BOOTS","GOLDEN_HELMET","GOLDEN_CHESTPLATE","GOLDEN_LEGGINGS","GOLDEN_BOOTS","DIAMOND_HELMET","DIAMOND_CHESTPLATE","DIAMOND_LEGGINGS","DIAMOND_BOOTS","NETHERITE_HELMET","NETHERITE_CHESTPLATE","NETHERITE_LEGGINGS","NETHERITE_BOOTS","SHIELD","BOW","CROSSBOW","ARROW","SPECTRAL_ARROW","TIPPED_ARROW","TRIDENT","MACE","TOTEM_OF_UNDYING","ENDER_PEARL","END_CRYSTAL","OBSIDIAN","RESPAWN_ANCHOR","GLOWSTONE","GOLDEN_APPLE","ENCHANTED_GOLDEN_APPLE","WOLF_ARMOR","LEATHER_HORSE_ARMOR","IRON_HORSE_ARMOR","GOLDEN_HORSE_ARMOR","DIAMOND_HORSE_ARMOR"};for(String n:names)pvp(n,pvpPrice(n));}
 private double pvpPrice(String n){if(n.contains("NETHERITE"))return 1800;if(n.contains("DIAMOND"))return 650;if(n.equals("MACE"))return 1200;if(n.equals("TRIDENT"))return 900;if(n.equals("TOTEM_OF_UNDYING"))return 700;if(n.equals("END_CRYSTAL"))return 180;if(n.equals("ENCHANTED_GOLDEN_APPLE"))return 2500;if(n.equals("GOLDEN_APPLE"))return 450;if(n.equals("OBSIDIAN"))return 45;if(n.equals("RESPAWN_ANCHOR"))return 120;if(n.equals("TIPPED_ARROW"))return 35;if(n.contains("HORSE_ARMOR")||n.equals("WOLF_ARMOR"))return 250;if(n.equals("BOW")||n.equals("CROSSBOW")||n.equals("SHIELD"))return 120;return 60;}
 private void loadFarmFood(){String[] names={"WHEAT","WHEAT_SEEDS","CARROT","POTATO","POISONOUS_POTATO","BEETROOT","BEETROOT_SEEDS","SUGAR_CANE","SUGAR","COCOA_BEANS","PUMPKIN","PUMPKIN_SEEDS","MELON","MELON_SLICE","MELON_SEEDS","NETHER_WART","CACTUS","BAMBOO","KELP","DRIED_KELP","DRIED_KELP_BLOCK","SWEET_BERRIES","GLOW_BERRIES","APPLE","GOLDEN_APPLE","ENCHANTED_GOLDEN_APPLE","BREAD","COOKIE","CAKE","PUMPKIN_PIE","BAKED_POTATO","GOLDEN_CARROT","BEEF","COOKED_BEEF","PORKCHOP","COOKED_PORKCHOP","CHICKEN","COOKED_CHICKEN","MUTTON","COOKED_MUTTON","RABBIT","COOKED_RABBIT","COD","COOKED_COD","SALMON","COOKED_SALMON","TROPICAL_FISH","PUFFERFISH","RABBIT_STEW","MUSHROOM_STEW","BEETROOT_SOUP","SUSPICIOUS_STEW","HONEY_BOTTLE","HONEYCOMB","EGG","BROWN_MUSHROOM","RED_MUSHROOM","CHORUS_FRUIT"};for(String n:names)farm(n,farmPrice(n));}
 private double farmPrice(String n){if(n.equals("ENCHANTED_GOLDEN_APPLE"))return 2500;if(n.equals("GOLDEN_APPLE"))return 450;if(n.equals("GOLDEN_CARROT"))return 90;if(n.startsWith("COOKED_"))return 28;if(n.equals("BEEF")||n.equals("PORKCHOP")||n.equals("MUTTON")||n.equals("CHICKEN")||n.equals("RABBIT"))return 15;if(n.contains("STEW")||n.equals("BEETROOT_SOUP"))return 40;if(n.equals("CAKE"))return 70;if(n.equals("PUMPKIN_PIE"))return 35;if(n.equals("COOKIE"))return 12;if(n.equals("BREAD"))return 18;if(n.equals("BAKED_POTATO"))return 14;if(n.equals("APPLE"))return 12;if(n.contains("SALMON")||n.contains("COD"))return n.startsWith("COOKED_")?28:16;if(n.equals("HONEY_BOTTLE"))return 30;if(n.equals("SUGAR_CANE")||n.equals("CACTUS")||n.equals("BAMBOO")||n.equals("KELP"))return 5;if(n.contains("SEEDS"))return 2;if(n.equals("WHEAT"))return 6;if(n.equals("CARROT")||n.equals("POTATO")||n.equals("BEETROOT"))return 7;if(n.equals("PUMPKIN")||n.equals("MELON"))return 12;if(n.equals("NETHER_WART"))return 10;if(n.contains("BERRIES"))return 9;return 8;}
 private double miningPrice(Material m){String n=m.name();if(n.contains("NETHERITE_BLOCK"))return 31500;if(n.contains("NETHERITE_INGOT"))return 3500;if(n.contains("SCRAP"))return 850;if(n.contains("ANCIENT"))return 750;if(n.contains("DIAMOND_BLOCK"))return 4500;if(n.equals("DIAMOND"))return 500;if(n.contains("DIAMOND_ORE"))return 450;if(n.contains("EMERALD_BLOCK"))return 3150;if(n.equals("EMERALD"))return 350;if(n.contains("EMERALD_ORE"))return 320;if(n.contains("GOLD_BLOCK"))return 990;if(n.contains("GOLD_INGOT"))return 110;if(n.contains("IRON_BLOCK"))return 675;if(n.contains("IRON_INGOT"))return 75;if(n.contains("COAL_BLOCK"))return 160;if(n.contains("AMETHYST"))return 80;if(n.contains("ECHO"))return 400;return 30;}
 private double defaultBlockPrice(Material m){String n=m.name();if(n.endsWith("_LOG")||n.endsWith("_WOOD")||n.endsWith("_STEM")||n.endsWith("_HYPHAE"))return 12;if(n.contains("GLASS"))return 8;if(n.contains("TERRACOTTA")||n.contains("CONCRETE"))return 10;if(n.contains("WOOL"))return 9;if(n.contains("PLANKS"))return 8;if(n.contains("SAND")||n.contains("GRAVEL"))return 5;if(n.contains("DIRT")||n.contains("MUD"))return 3;return 7;}
 private void loadBooks(){books.clear();List<Enchantment> all=new ArrayList<>();for(Enchantment e:Registry.ENCHANTMENT)all.add(e);all.sort(Comparator.comparing(e->e.getKey().getKey()));for(Enchantment e:all)for(int lvl=e.getStartLevel();lvl<=e.getMaxLevel();lvl++)books.add(new BookOffer(e,lvl,bookBasePrice(e,lvl)));}
 private double bookBasePrice(Enchantment e,int lvl){double base=150+lvl*125;String n=e.getKey().getKey();if(n.contains("mending"))base=1500;if(n.contains("silk_touch"))base=1000;if(n.contains("fortune")||n.contains("looting"))base+=500;if(n.contains("protection")||n.contains("sharpness")||n.contains("efficiency")||n.contains("power"))base+=250;return base;}
 private void loadData(){if(!getDataFolder().exists())getDataFolder().mkdirs();dataFile=new File(getDataFolder(),"playerdata.yml");data=YamlConfiguration.loadConfiguration(dataFile);}private void saveData(){try{data.save(dataFile);}catch(IOException e){getLogger().severe(e.getMessage());}}
 @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!c.getName().equalsIgnoreCase("sell"))return false;if(s instanceof Player p)openSellMenu(p);return true;}
 private void openSellMenu(Player p){Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.SELL,p.getUniqueId(),0,Category.OTHER),54,"§8SATIŞ MENÜSÜ");i.setItem(BLOCKS_SLOT,button(Material.GRASS_BLOCK,"§a§lBLOKLAR",List.of("§eTıkla!")));i.setItem(MINING_SLOT,button(Material.DIAMOND,"§b§lMADEN",List.of("§eTıkla!")));i.setItem(BOOKS_SLOT,button(Material.ENCHANTED_BOOK,"§d§lBÜYÜLÜ KİTAPLAR",List.of("§eTıkla!")));i.setItem(SELL_BUTTON_SLOT,button(Material.EMERALD,"§a§lSAT",List.of("§7Üstteki 45 slota eşyalarını koy.","§eSatmak için tıkla!")));i.setItem(FARM_SLOT,button(Material.WHEAT,"§6§lTARIM & YEMEK",List.of("§7Tarım ürünleri ve yiyecekler.","§eTıkla!")));i.setItem(PVP_SLOT,button(Material.NETHERITE_SWORD,"§c§lPVP",List.of("§7Silahlar, zırhlar ve PvP malzemeleri.","§eTıkla!")));p.openInventory(i);}
 private void openCategory(Player p,Category cat){Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.CATEGORY,p.getUniqueId(),0,cat),54,"§8"+cat.title+" KATEGORİSİ");fill(i,Material.GRAY_STAINED_GLASS_PANE," ");double earned=getEarned(p,cat);int completed=getCompletedLevels(earned),current=Math.min(completed+1,20);for(int x=0;x<20;x++){int level=x+1;Material pane=level<=completed?Material.LIGHT_BLUE_STAINED_GLASS_PANE:(level==current&&completed<20?Material.YELLOW_STAINED_GLASS_PANE:Material.RED_STAINED_GLASS_PANE);double start=x==0?0:LEVEL_TARGETS[x-1],target=LEVEL_TARGETS[x];String status=level<=completed?"§bTAMAMLANDI":(level==current&&completed<20?"§eİLERLİYOR":"§cKİLİTLİ");i.setItem(LEVEL_SLOTS[x],button(pane,"§f§lLEVEL "+level,List.of(status,"§7Hedef: §6$"+money(target),"§7Aralık: §f$"+money(start)+" §7→ §f$"+money(target),"§7Bitince: §a"+String.format(Locale.US,"%.1fx",1.0+level*.1))));}i.setItem(4,progressBook(p,cat));i.setItem(1,button(cat.icon,"§e§l"+cat.title+" EŞYALARI",List.of("§7Eşyaları ve fiyatlarını gör.","§eTıkla!")));i.setItem(53,button(Material.ARROW,"§eGeri",List.of()));p.openInventory(i);}
 private void openItems(Player p,Category cat,int page){if(cat==Category.BOOKS){openBookItems(p,page);return;}if(cat==Category.PVP){openPvpItems(p,page);return;}String q=searchNorm(searches.getOrDefault(p.getUniqueId(),""));SortMode mode=sortModes.getOrDefault(p.getUniqueId(),SortMode.GROUP);List<Material> items=new ArrayList<>();for(Material m:prices.keySet())if(categories.get(m)==cat&&(q.isEmpty()||searchNorm(pretty(m)).contains(q)||searchNorm(m.name()).contains(q)))items.add(m);Comparator<Material> cmp=Comparator.comparing((Material m)->groupKey(m,cat)).thenComparing((Material m)->pretty(m).toLowerCase(Locale.ROOT));if(mode==SortMode.AZ)cmp=Comparator.comparing((Material m)->pretty(m).toLowerCase(Locale.ROOT));else if(mode==SortMode.PRICE_LOW)cmp=Comparator.comparingDouble((Material m)->prices.get(m)).thenComparing((Material m)->pretty(m));else if(mode==SortMode.PRICE_HIGH)cmp=Comparator.comparingDouble((Material m)->prices.get(m)).reversed().thenComparing((Material m)->pretty(m));items.sort(cmp);int per=45,max=Math.max(0,(items.size()-1)/per);page=Math.max(0,Math.min(page,max));Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.ITEMS,p.getUniqueId(),page,cat),54,"§8"+cat.title+" §7• Sayfa "+(page+1)+"/"+(max+1));double mult=getMultiplier(p,cat);int start=page*per;for(int s=0;s<per&&start+s<items.size();s++){Material m=items.get(start+s);double base=prices.get(m);ItemStack shown=button(m,"§f"+pretty(m),List.of("§7Normal fiyat: §e$"+money(base),"§7Çarpanın: §a"+String.format(Locale.US,"%.1fx",mult),"§7Satış fiyatın: §6$"+money(base*mult)));ItemMeta shownMeta=shown.getItemMeta();shownMeta.displayName(Component.translatable(m.translationKey()).color(NamedTextColor.WHITE));shown.setItemMeta(shownMeta);i.setItem(s,shown);}nav(i,p,page,max);p.openInventory(i);}
 private void openPvpItems(Player p,int page){String q=searchNorm(searches.getOrDefault(p.getUniqueId(),""));SortMode mode=sortModes.getOrDefault(p.getUniqueId(),SortMode.GROUP);List<PvpDisplay> list=new ArrayList<>();for(Material m:prices.keySet())if(categories.get(m)==Category.PVP&&m!=Material.TIPPED_ARROW){String name=pretty(m);if(q.isEmpty()||searchNorm(name).contains(q)||searchNorm(m.name()).contains(q))list.add(new PvpDisplay(new ItemStack(m),name,prices.get(m),groupKey(m,Category.PVP)));}for(PotionType pt:PotionType.values()){String n=pt.name();if(n.equals("WATER")||n.equals("MUNDANE")||n.equals("THICK")||n.equals("AWKWARD")||n.equals("UNCRAFTABLE"))continue;String name=tippedArrowName(pt);if(!q.isEmpty()&&!searchNorm(name).contains(q)&&!searchNorm(n).contains(q))continue;ItemStack it=new ItemStack(Material.TIPPED_ARROW);PotionMeta pm=(PotionMeta)it.getItemMeta();try{pm.setBasePotionType(pt);}catch(Exception ex){continue;}it.setItemMeta(pm);list.add(new PvpDisplay(it,name,prices.getOrDefault(Material.TIPPED_ARROW,35d),"07_menzilli"));}Comparator<PvpDisplay> cmp=Comparator.comparing(PvpDisplay::group).thenComparing(PvpDisplay::name);if(mode==SortMode.AZ)cmp=Comparator.comparing(PvpDisplay::name);else if(mode==SortMode.PRICE_LOW)cmp=Comparator.comparingDouble(PvpDisplay::price).thenComparing(PvpDisplay::name);else if(mode==SortMode.PRICE_HIGH)cmp=Comparator.comparingDouble(PvpDisplay::price).reversed().thenComparing(PvpDisplay::name);list.sort(cmp);int per=45,max=Math.max(0,(list.size()-1)/per);page=Math.max(0,Math.min(page,max));Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.ITEMS,p.getUniqueId(),page,Category.PVP),54,"§8PVP §7• Sayfa "+(page+1)+"/"+(max+1));double mult=getMultiplier(p,Category.PVP);int start=page*per;for(int x=0;x<per&&start+x<list.size();x++){PvpDisplay d=list.get(start+x);ItemStack it=d.stack.clone();ItemMeta meta=it.getItemMeta();meta.setDisplayName("§f"+d.name);meta.setLore(List.of("§7Normal fiyat: §e$"+money(d.price),"§7Çarpanın: §a"+String.format(Locale.US,"%.1fx",mult),"§7Satış fiyatın: §6$"+money(d.price*mult)));it.setItemMeta(meta);i.setItem(x,it);}nav(i,p,page,max);p.openInventory(i);}
 private String tippedArrowName(PotionType p){String n=p.name();String base=n.replace("LONG_","").replace("STRONG_","");String tr=switch(base){case "NIGHT_VISION"->"Gece Görüşü";case "INVISIBILITY"->"Görünmezlik";case "LEAPING"->"Sıçrama";case "FIRE_RESISTANCE"->"Ateş Direnci";case "SWIFTNESS"->"Hız";case "SLOWNESS"->"Yavaşlık";case "WATER_BREATHING"->"Suda Nefes Alma";case "HEALING"->"İyileştirme";case "HARMING"->"Hasar";case "POISON"->"Zehir";case "REGENERATION"->"Yenilenme";case "STRENGTH"->"Güç";case "WEAKNESS"->"Zayıflık";case "LUCK"->"Şans";case "TURTLE_MASTER"->"Kaplumbağa Ustası";case "SLOW_FALLING"->"Yavaş Düşüş";case "WIND_CHARGED"->"Rüzgar Yüklü";case "WEAVING"->"Dokuma";case "OOZING"->"Sızıntı";case "INFESTED"->"İstila";default->prettyKey(base);};String extra=n.startsWith("LONG_")?" (Uzun)":n.startsWith("STRONG_")?" (Güçlü)":"";return tr+" Oku"+extra;}
 private void openBookItems(Player p,int page){String q=searchNorm(searches.getOrDefault(p.getUniqueId(),""));SortMode mode=sortModes.getOrDefault(p.getUniqueId(),SortMode.GROUP);List<BookOffer> list=new ArrayList<>();for(BookOffer b:books){String n=prettyEnchant(b.enchant)+" "+roman(b.level);if(q.isEmpty()||searchNorm(n).contains(q)||searchNorm(b.enchant.getKey().getKey()).contains(q))list.add(b);}Comparator<BookOffer> cmp=Comparator.comparing((BookOffer b)->b.enchant.getKey().getKey()).thenComparingInt(BookOffer::level);if(mode==SortMode.AZ)cmp=Comparator.comparing(b->(prettyEnchant(b.enchant)+" "+String.format("%02d",b.level)).toLowerCase(Locale.ROOT));else if(mode==SortMode.PRICE_LOW)cmp=Comparator.comparingDouble(BookOffer::price).thenComparing(b->prettyEnchant(b.enchant));else if(mode==SortMode.PRICE_HIGH)cmp=Comparator.comparingDouble(BookOffer::price).reversed().thenComparing(b->prettyEnchant(b.enchant));list.sort(cmp);int per=45,max=Math.max(0,(list.size()-1)/per);page=Math.max(0,Math.min(page,max));Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.ITEMS,p.getUniqueId(),page,Category.BOOKS),54,"§8BÜYÜLÜ KİTAPLAR §7• Sayfa "+(page+1)+"/"+(max+1));double mult=getMultiplier(p,Category.BOOKS);int start=page*per;for(int s=0;s<per&&start+s<list.size();s++){BookOffer b=list.get(start+s);ItemStack it=new ItemStack(Material.ENCHANTED_BOOK);EnchantmentStorageMeta meta=(EnchantmentStorageMeta)it.getItemMeta();meta.addStoredEnchant(b.enchant,b.level,true);meta.displayName(Component.translatable(b.enchant.translationKey()).append(Component.text(" "+roman(b.level))).color(NamedTextColor.LIGHT_PURPLE));meta.setLore(List.of("§7Normal fiyat: §e$"+money(b.price),"§7Çarpanın: §a"+String.format(Locale.US,"%.1fx",mult),"§7Satış fiyatın: §6$"+money(b.price*mult)));it.setItemMeta(meta);i.setItem(s,it);}nav(i,p,page,max);p.openInventory(i);}
 private void nav(Inventory i,Player p,int page,int max){SortMode mode=sortModes.getOrDefault(p.getUniqueId(),SortMode.GROUP);String q=searches.getOrDefault(p.getUniqueId(),"");i.setItem(45,button(Material.BOOK,"§eİlerleme",List.of()));i.setItem(46,button(Material.COMPASS,"§b§lARA",List.of(q.isEmpty()?"§7Arama yok":"§7Arama: §f"+q,"§eTıkla ve sohbete eşya adını yaz!")));i.setItem(47,button(Material.HOPPER,"§6§lSIRALA",List.of("§7Şu an: §f"+mode.label,"§eSonraki moda geçmek için tıkla!")));if(page>0)i.setItem(48,button(Material.ARROW,"§eÖnceki Sayfa",List.of()));if(page<max)i.setItem(50,button(Material.ARROW,"§eSonraki Sayfa",List.of()));if(!q.isEmpty())i.setItem(51,button(Material.MILK_BUCKET,"§cAramayı Temizle",List.of("§7Tüm eşyaları tekrar göster.")));i.setItem(53,button(Material.BARRIER,"§cGeri",List.of()));}
 @EventHandler public void onChat(AsyncPlayerChatEvent e){Player p=e.getPlayer();Category cat=awaitingSearch.remove(p.getUniqueId());if(cat==null)return;e.setCancelled(true);String text=e.getMessage().trim();Bukkit.getScheduler().runTask(this,()->{if(text.equalsIgnoreCase("iptal")||text.equalsIgnoreCase("cancel")){p.sendMessage("§cArama iptal edildi.");openItems(p,cat,0);return;}searches.put(p.getUniqueId(),text);p.sendMessage("§aArama: §f"+text);openItems(p,cat,0);});}
 private ItemStack progressBook(Player p,Category cat){double e=getEarned(p,cat);int completed=getCompletedLevels(e);double mult=getMultiplier(p,cat);if(completed>=20)return button(Material.BOOK,"§e§l"+cat.title+" İLERLEMESİ",List.of("§7Tamamlanan: §f20§7/20","§7Çarpan: §a3.0x","§7Toplam: §6$"+money(e),"§bTÜM LEVELLAR TAMAMLANDI!"));double target=LEVEL_TARGETS[completed];return button(Material.BOOK,"§e§l"+cat.title+" İLERLEMESİ",List.of("§7Şu anki level: §f"+(completed+1)+"§7/20","§7Çarpan: §a"+String.format(Locale.US,"%.1fx",mult),"§7Toplam: §6$"+money(e),"§7İlerleme: §e$"+money(e)+" §7/ §e$"+money(target),"§7Hedef: §6$"+money(target)));}
 private void fill(Inventory i,Material m,String n){for(int s=0;s<i.getSize();s++)i.setItem(s,button(m,n,List.of()));}private ItemStack button(Material m,String n,List<String> lore){ItemStack it=new ItemStack(m);ItemMeta meta=it.getItemMeta();meta.setDisplayName(n);meta.setLore(lore);it.setItemMeta(meta);return it;}
 @EventHandler public void onInventoryClick(InventoryClickEvent e){if(!(e.getInventory().getHolder() instanceof MenuHolder h)||!(e.getWhoClicked() instanceof Player p))return;if(!h.owner.equals(p.getUniqueId())){e.setCancelled(true);return;}int s=e.getRawSlot();if(h.type==MenuType.SELL){if(s>=SELL_AREA_END&&s<54){e.setCancelled(true);if(s==BLOCKS_SLOT||s==MINING_SLOT||s==BOOKS_SLOT||s==FARM_SLOT||s==PVP_SLOT){returnSellItems(p,e.getInventory());Category c=s==BLOCKS_SLOT?Category.BLOCKS:s==MINING_SLOT?Category.MINING:s==BOOKS_SLOT?Category.BOOKS:s==FARM_SLOT?Category.FARM_FOOD:Category.PVP;searches.remove(p.getUniqueId());sortModes.put(p.getUniqueId(),SortMode.GROUP);openCategory(p,c);}else if(s==SELL_BUTTON_SLOT)sellItems(p,e.getInventory());}return;}e.setCancelled(true);if(h.type==MenuType.CATEGORY){if(s==1)openItems(p,h.cat,0);else if(s==53)openSellMenu(p);}else if(h.type==MenuType.ITEMS){if(s==45||s==53)openCategory(p,h.cat);else if(s==46){awaitingSearch.put(p.getUniqueId(),h.cat);p.closeInventory();p.sendMessage("§b§lARAMA §7» §fAramak istediğin eşyanın adını sohbete yaz.");p.sendMessage("§7İptal etmek için §ciptal §7yaz.");}else if(s==47){sortModes.put(p.getUniqueId(),sortModes.getOrDefault(p.getUniqueId(),SortMode.GROUP).next());openItems(p,h.cat,0);}else if(s==48&&h.page>0)openItems(p,h.cat,h.page-1);else if(s==50)openItems(p,h.cat,h.page+1);else if(s==51&&!searches.getOrDefault(p.getUniqueId(),"").isEmpty()){searches.remove(p.getUniqueId());openItems(p,h.cat,0);}}}
 private void sellItems(Player p,Inventory i){double total=0;Map<Category,Double> earned=new EnumMap<>(Category.class);int amount=0;for(int s=0;s<SELL_AREA_END;s++){ItemStack it=i.getItem(s);if(it==null||it.getType().isAir())continue;Category c;double base;if(it.getType()==Material.ENCHANTED_BOOK){BookOffer b=matchBook(it);if(b==null)continue;c=Category.BOOKS;base=b.price;}else{Double pr=prices.get(it.getType());if(pr==null)continue;base=pr;c=categories.getOrDefault(it.getType(),Category.OTHER);}double line=base*it.getAmount()*getMultiplier(p,c);total+=line;if(c!=Category.OTHER)earned.merge(c,line,Double::sum);amount+=it.getAmount();i.setItem(s,null);}if(amount==0){p.sendMessage("§cSatılabilir bir eşya koymadın.");return;}economy.depositPlayer(p,total);earned.forEach((c,v)->addEarned(p,c,v));p.sendMessage("§a"+amount+" eşya sattın ve §e$"+money(total)+" §akazandın!");p.closeInventory();}
 private BookOffer matchBook(ItemStack it){if(!(it.getItemMeta() instanceof EnchantmentStorageMeta meta))return null;Map<Enchantment,Integer> es=meta.getStoredEnchants();if(es.size()!=1)return null;Map.Entry<Enchantment,Integer> x=es.entrySet().iterator().next();for(BookOffer b:books)if(b.enchant.equals(x.getKey())&&b.level==x.getValue())return b;return null;}
 private void addEarned(Player p,Category c,double a){String path=p.getUniqueId()+"."+c.key+".earned";double before=data.getDouble(path,0),after=before+a;int old=getCompletedLevels(before);data.set(path,after);saveData();int now=getCompletedLevels(after);if(now>old)p.sendMessage("§6§lLEVEL TAMAMLANDI! §e"+c.title+" leveli: §f"+now+" §7• Yeni çarpan: §a"+String.format(Locale.US,"%.1fx",getMultiplierFromEarned(after)));}
 private double getEarned(Player p,Category c){return data.getDouble(p.getUniqueId()+"."+c.key+".earned",0);}private int getCompletedLevels(double e){int n=0;for(double t:LEVEL_TARGETS){if(e>=t)n++;else break;}return n;}private double getMultiplier(Player p,Category c){return c==Category.OTHER?1:getMultiplierFromEarned(getEarned(p,c));}private double getMultiplierFromEarned(double e){return Math.min(3,1+getCompletedLevels(e)*.1);}private String searchNorm(String s){if(s==null)return "";return java.text.Normalizer.normalize(s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).replace("ı","i").replace("ş","s").replace("ç","c").replace("ğ","g").replace("ö","o").replace("ü","u");}private String groupKey(Material m,Category c){String n=m.name();if(c==Category.PVP){if(n.contains("NETHERITE"))return "01_netherit";if(n.contains("DIAMOND"))return "02_elmas";if(n.contains("IRON")||n.contains("CHAINMAIL"))return "03_demir";if(n.contains("GOLDEN")||n.contains("GOLD_"))return "04_altin";if(n.contains("LEATHER")||n.equals("WOLF_ARMOR"))return "05_hayvan_zirhi";if(n.contains("SWORD")||n.contains("AXE")||n.equals("MACE")||n.equals("TRIDENT"))return "06_silah";if(n.contains("BOW")||n.contains("ARROW"))return "07_menzilli";if(n.equals("OBSIDIAN")||n.equals("END_CRYSTAL")||n.equals("RESPAWN_ANCHOR")||n.equals("GLOWSTONE"))return "08_kristal";return "09_diger";}if(c==Category.FARM_FOOD){if(n.startsWith("COOKED_")||n.contains("BAKED"))return "03_pismis";if(n.contains("BEEF")||n.contains("PORK")||n.contains("CHICKEN")||n.contains("MUTTON")||n.contains("RABBIT")||n.contains("COD")||n.contains("SALMON")||n.contains("FISH"))return "02_hayvansal";if(n.contains("WHEAT")||n.contains("SEED")||n.contains("CARROT")||n.contains("POTATO")||n.contains("BEETROOT")||n.contains("MELON")||n.contains("PUMPKIN")||n.contains("CANE")||n.contains("WART")||n.contains("BERR")||n.contains("CACTUS")||n.contains("BAMBOO")||n.contains("KELP"))return "01_tarim";return "04_yemek";}if(c==Category.BLOCKS){String[] families={"OAK","SPRUCE","BIRCH","JUNGLE","ACACIA","DARK_OAK","MANGROVE","CHERRY","BAMBOO","CRIMSON","WARPED","END","NETHER","PRISMARINE","COPPER","STONE","DEEPSLATE","SAND","GLASS","WOOL","CONCRETE","TERRACOTTA"};for(int x=0;x<families.length;x++)if(n.contains(families[x]))return String.format("%02d_%s",x,families[x]);}if(c==Category.MINING){String[] f={"COAL","IRON","COPPER","GOLD","REDSTONE","LAPIS","DIAMOND","EMERALD","QUARTZ","AMETHYST","NETHERITE","ANCIENT","ECHO"};for(int x=0;x<f.length;x++)if(n.contains(f[x]))return String.format("%02d_%s",x,f[x]);}return "99_"+n;}private String pretty(Material m){return TurkishNames.material(m);}private String prettyEnchant(Enchantment e){return TurkishNames.enchant(e);}private String prettyKey(String n){String[] a=n.toLowerCase(Locale.ROOT).split("_");StringBuilder r=new StringBuilder();for(String x:a){if(!r.isEmpty())r.append(' ');r.append(Character.toUpperCase(x.charAt(0))).append(x.substring(1));}return r.toString();}private String roman(int n){String[] r={"","I","II","III","IV","V","VI","VII","VIII","IX","X"};return n<r.length?r[n]:String.valueOf(n);}private String money(double a){return String.format(Locale.US,"%,.2f",a);}
 @EventHandler public void onInventoryClose(InventoryCloseEvent e){if(e.getInventory().getHolder() instanceof MenuHolder h&&h.type==MenuType.SELL&&e.getPlayer() instanceof Player p)returnSellItems(p,e.getInventory());}private void returnSellItems(Player p,Inventory i){for(int s=0;s<SELL_AREA_END;s++){ItemStack it=i.getItem(s);if(it==null||it.getType().isAir())continue;i.setItem(s,null);Map<Integer,ItemStack> left=p.getInventory().addItem(it);left.values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));}}@Override public void onDisable(){saveData();}
 private record BookOffer(Enchantment enchant,int level,double price){}private record PvpDisplay(ItemStack stack,String name,double price,String group){}private enum SortMode{GROUP("Grup"),PRICE_HIGH("Fiyat: Büyük → Küçük"),PRICE_LOW("Fiyat: Küçük → Büyük"),AZ("A-Z");final String label;SortMode(String l){label=l;}SortMode next(){return values()[(ordinal()+1)%values().length];}}private enum Category{BLOCKS("blocks","BLOK",Material.GRASS_BLOCK),MINING("mining","MADEN",Material.DIAMOND),BOOKS("books","BÜYÜLÜ KİTAP",Material.ENCHANTED_BOOK),FARM_FOOD("farm_food","TARIM & YEMEK",Material.WHEAT),PVP("pvp","PVP",Material.NETHERITE_SWORD),OTHER("other","DİĞER",Material.CHEST);final String key,title;final Material icon;Category(String k,String t,Material i){key=k;title=t;icon=i;}}private enum MenuType{SELL,CATEGORY,ITEMS}private static final class MenuHolder implements InventoryHolder{final MenuType type;final UUID owner;final int page;final Category cat;MenuHolder(MenuType t,UUID o,int p,Category c){type=t;owner=o;page=p;cat=c;}@Override public Inventory getInventory(){return null;}}
}
